// =====================================================================
// YEAR 11 — Inheritance, variation & evolution (AQA 4.6)
// =====================================================================
const TRAITS = [
  { L: "T", dom: "tall", rec: "dwarf", org: "pea plants" },
  { L: "B", dom: "black fur", rec: "brown fur", org: "mice" },
  { L: "R", dom: "round seeds", rec: "wrinkled seeds", org: "pea plants" },
  { L: "F", dom: "no cystic fibrosis", rec: "cystic fibrosis", org: "humans" },
  { L: "D", dom: "polydactyly (extra digits)", rec: "five digits", org: "humans" },
  { L: "P", dom: "purple flowers", rec: "white flowers", org: "pea plants" },
  { L: "G", dom: "green pods", rec: "yellow pods", org: "pea plants" },
];
function genCross(rng) {
  const t = pick(rng, TRAITS), A = t.L, a = t.L.toLowerCase();
  const geno = [A + A, A + a, a + a];
  const crosses = [[1, 1], [1, 2], [0, 2], [0, 1], [2, 1]];
  const [i, j] = pick(rng, crosses);
  const p1 = geno[i], p2 = geno[j];
  let recCount = 0, het = 0;
  const kids = [];
  for (const x of p1) for (const y of p2) { const g = [x, y].sort().join(""); kids.push(g); if (g === a + a) recCount++; if (g === A + a || g === a + A) het++; }
  const ask = ri(rng, 0, 2);
  const show = kids.map((k) => (k[0] === a && k[1] === A ? A + a : k)).join(", ");
  const base = "In " + t.org + ", the allele for " + t.dom + " (" + A + ") is dominant to the allele for " + t.rec + " (" + a + "). Two parents with genotypes <b>" + p1 + "</b> and <b>" + p2 + "</b> are crossed. ";
  const steps0 = ["Gametes: " + p1[0] + " or " + p1[1] + " from one parent; " + p2[0] + " or " + p2[1] + " from the other", "Punnett square offspring: " + show];
  if (ask === 0) {
    const v = recCount * 25;
    return { type: "number", q: base + "What is the percentage chance that an offspring has " + t.rec + "?", value: v, tol: 0.01, unit: "%", answer: v + "%",
      steps: steps0.concat(["Only " + a + a + " shows " + t.rec + ": " + recCount + " out of 4", "Probability = " + recCount + "/4 = " + v + "%"]), explain: "A recessive characteristic only appears when two recessive alleles are present (homozygous recessive).", hint: "Draw a Punnett square and count the homozygous recessive boxes." };
  }
  if (ask === 1) {
    const v = (4 - recCount) * 25;
    return { type: "number", q: base + "What is the percentage chance that an offspring has " + t.dom + "?", value: v, tol: 0.01, unit: "%", answer: v + "%",
      steps: steps0.concat(["Any genotype with at least one " + A + " shows " + t.dom + ": " + (4 - recCount) + " out of 4", "Probability = " + (4 - recCount) + "/4 = " + v + "%"]), explain: "A dominant allele is expressed even if only one copy is present (homozygous dominant or heterozygous).", hint: "Count boxes with at least one capital letter." };
  }
  const v = het * 25;
  return { type: "number", q: base + "What percentage of the offspring are expected to be heterozygous?", value: v, tol: 0.01, unit: "%", answer: v + "%",
    steps: steps0.concat(["Heterozygous = one dominant and one recessive allele (" + A + a + "): " + het + " out of 4", "= " + v + "%"]), explain: "Heterozygous means two different alleles; homozygous means two identical alleles.", hint: "Count the boxes with one capital and one lower-case letter." };
}

